-- Réécriture des scripts d’entretien (section « methodologie ») pour le mode
-- pas à pas : une phase = un moment de l’entretien, une étape = une consigne
-- courte avec, si utile, la phrase-clé à dire. Sources : voir
-- scripts/RAPPORT-scripts-entretiens-pas-a-pas-2026-09-29.md.
--
-- Périmètre : uniquement les types de « Pharmacie Rome Village » (seule
-- officine qui avait du contenu). La section « facturation » n’est pas touchée.
--
-- Sauvegarde : l’ancien contenu est copié dans
-- public.entretien_items_sauvegarde_20260929 (RLS activée, aucune policy : lisible
-- seulement via le service role / l’éditeur SQL). Pour revenir en arrière :
--   delete from entretien_items ei using types_entretien te, officines o
--    where ei.type_entretien_id = te.id and te.officine_id = o.id
--      and o.nom = 'Pharmacie Rome Village' and ei.section = 'methodologie';
--   insert into entretien_items select * from entretien_items_sauvegarde_20260929;

create table if not exists public.entretien_items_sauvegarde_20260929 as
  select ei.* from public.entretien_items ei
  where ei.section = 'methodologie';

alter table public.entretien_items_sauvegarde_20260929 enable row level security;

delete from public.entretien_items ei
using public.types_entretien te, public.officines o
where ei.type_entretien_id = te.id
  and te.officine_id = o.id
  and o.nom = 'Pharmacie Rome Village'
  and ei.section = 'methodologie';

-- Lignes : [clé du type, phase, code du type d’item, contenu].
-- Code : q = question, e = explication, a = alerte, chaîne vide = non typé (consigne).
insert into public.entretien_items (type_entretien_id, section, contenu, ordre, phase, type_item)
select
  tc.type_id,
  'methodologie',
  s.elem->>3,
  (row_number() over (partition by tc.type_id order by s.ord) - 1)::int,
  s.elem->>1,
  case s.elem->>2 when 'q' then 'question' when 'e' then 'explication' when 'a' then 'alerte' else null end
from jsonb_array_elements($json$[
    ["avk","Évaluation · Accueil","e","Présenter l’objectif : faire connaître le traitement, vérifier sa bonne prise et définir avec le patient un programme d’entretiens thématiques."],
    ["avk","Évaluation · Accueil","","Recevoir le patient dans l’espace de confidentialité et vérifier son accord (bulletin d’adhésion signé)."],
    ["avk","Évaluation · Recueil","","Relever l’AVK prescrit, la posologie, la date de début et les prescripteurs."],
    ["avk","Évaluation · Recueil","","Relever les autres traitements au long cours et les médicaments ou compléments pris sans ordonnance."],
    ["avk","Évaluation · Recueil","","Noter l’historique des AVK : molécules, dates, changements de traitement, accidents éventuels."],
    ["avk","Évaluation · Recueil","","Vérifier l’absence de contre-indication absolue ou relative (RCP) et noter le laboratoire qui dose l’INR."],
    ["avk","Évaluation · Recueil","q","Quelles sont vos habitudes de vie : alimentation, alcool, tabac, activité physique, sport de contact, bricolage, jardinage, voyages ?"],
    ["avk","Évaluation · Recueil","","Repérer les difficultés motrices, cognitives ou sensorielles qui nécessitent une aide. Vérifier si le patient a un carnet de suivi AVK."],
    ["avk","Évaluation · Appropriation du traitement","q","Comment vivez-vous globalement votre traitement ?"],
    ["avk","Évaluation · Appropriation du traitement","q","À quoi sert votre traitement AVK ? Pourquoi vous l’a-t-on prescrit ?"],
    ["avk","Évaluation · Appropriation du traitement","q","Savez-vous que ce traitement présente des risques ? Lesquels ?"],
    ["avk","Évaluation · Appropriation du traitement","q","Savez-vous qu’il demande une surveillance biologique (INR) ?"],
    ["avk","Évaluation · Appropriation du traitement","","Pour chaque réponse, noter : acquis, partiellement acquis ou non acquis."],
    ["avk","Évaluation · Observance","q","Connaissez-vous la dose prescrite par votre médecin ? La respectez-vous ?"],
    ["avk","Évaluation · Observance","q","À quelle heure prenez-vous ce médicament ? Le prenez-vous tous les jours à la même heure ?"],
    ["avk","Évaluation · Observance","q","Vous arrive-t-il d’oublier votre traitement ? Que faites-vous dans ce cas ?"],
    ["avk","Évaluation · Observance","e","En cas d’oubli : la dose peut être prise dans les 8 heures suivant l’heure habituelle, au-delà on saute la prise. Jamais de dose double. Noter l’oubli dans le carnet et prévenir le médecin."],
    ["avk","Évaluation · Observance","q","Notez-vous vos prises et vos oublis éventuels dans le carnet de suivi ?"],
    ["avk","Évaluation · Coordination","q","Quels autres professionnels de santé voyez-vous ? Leur présentez-vous la carte « Je prends un traitement par AVK » ?"],
    ["avk","Évaluation · Coordination","e","Prévenir le médecin avant toute intervention, même bénigne (petite chirurgie, extraction dentaire), et en cas de changement de situation."],
    ["avk","Évaluation · Coordination","a","Grossesse : les AVK sont à éviter sauf cas très particulier. Contraception efficace pendant le traitement et jusqu’à 3 jours (acénocoumarol), 7 jours (fluindione) ou 10 jours (warfarine) après l’arrêt. Si grossesse suspectée : prévenir le médecin, sans arrêter l’AVK de soi-même."],
    ["avk","Évaluation · Clôture","q","Avez-vous des questions ou des remarques ?"],
    ["avk","Évaluation · Clôture","","Compléter le bilan de l’entretien et le plan d’accompagnement (entretiens à programmer selon les points non acquis)."],
    ["avk","Évaluation · Clôture","","Fixer les prochains rendez-vous : surveillance biologique, observance, effets du traitement, vie quotidienne et alimentation."],
    ["avk","Thème · Surveillance biologique","e","L’INR mesure l’action de l’AVK sur la fluidité du sang. Cet examen est indispensable pendant toute la durée du traitement."],
    ["avk","Thème · Surveillance biologique","q","Connaissez-vous votre INR cible et sa fourchette ? Sont-ils notés dans votre carnet ?"],
    ["avk","Thème · Surveillance biologique","e","Contrôle au moins une fois par mois (plus souvent au début), le matin. Récupérer le résultat le jour même, le noter dans le carnet et le transmettre au médecin."],
    ["avk","Thème · Surveillance biologique","a","INR hors de la fourchette : au-dessus, risque de saignement ; en dessous, risque de caillot. Prévenir le médecin sans attendre."],
    ["avk","Thème · Surveillance biologique","e","Un contrôle supplémentaire est nécessaire après un nouveau médicament ou un changement d’alimentation."],
    ["avk","Thème · Observance","q","Prenez-vous votre AVK chaque jour à la même heure (de préférence le soir) ?"],
    ["avk","Thème · Observance","e","Toute modification de dose est décidée par le médecin, jamais par le patient."],
    ["avk","Thème · Observance","q","Remplissez-vous le carnet à chaque INR (résultat, dose prise, incident) ?"],
    ["avk","Thème · Observance","e","En déplacement : emporter l’ordonnance, le traitement en quantité suffisante et le carnet ; garder le traitement en cabine ; décalage horaire : demander conseil au médecin."],
    ["avk","Thème · Observance","e","Conserver les comprimés dans leur emballage d’origine et y replacer les fractions non utilisées juste après la découpe."],
    ["avk","Thème · Effets du traitement","q","Avez-vous eu un saignement, des bleus ou d’autres effets depuis notre dernier entretien ?"],
    ["avk","Thème · Effets du traitement","a","Saignement même minime (gencives, nez, œil rouge, sang dans les urines ou les selles, selles noires, règles abondantes, hématomes, vomissements ou crachats sanglants, saignement qui ne s’arrête pas) : contacter rapidement un médecin."],
    ["avk","Thème · Effets du traitement","a","Signes d’un saignement interne (fatigue ou essoufflement inhabituels, pâleur, mal de tête persistant, malaise inexpliqué) : consulter."],
    ["avk","Thème · Vie quotidienne et alimentation","e","Les aliments riches en vitamine K (brocolis, asperges, épinards, choux, endives, salade frisée…) ne sont pas interdits : les répartir régulièrement, sans excès. Alcool avec modération."],
    ["avk","Thème · Vie quotidienne et alimentation","a","Aucun autre médicament sans avis (aspirine, anti-inflammatoires, millepertuis…), même vendu sans ordonnance. Paracétamol : pas plus de 4 jours à 4 g par jour."],
    ["avk","Thème · Vie quotidienne et alimentation","e","Signaler l’AVK à tout professionnel de santé. Avis médical avant extraction dentaire, injection, petite chirurgie, pédicurie ou voyage."],
    ["avk","Thème · Vie quotidienne et alimentation","e","Éviter les sports violents et les travaux pouvant entraîner une coupure ou une chute."],

