    ["bpm","Entretien de recueil · Prise des médicaments","q","Vous reste-t-il des médicaments dans les boîtes à la fin du mois ? Êtes-vous parfois en rupture ? En avez-vous en grande quantité chez vous ?"],
    ["bpm","Entretien de recueil · Prise des médicaments","q","Avez-vous tendance à oublier certains médicaments ? Lesquels ?"],
    ["bpm","Entretien de recueil · Prise des médicaments","q","Vos médicaments sont-ils préparés par vous ou par quelqu’un d’autre ? Utilisez-vous un pilulier ?"],
    ["bpm","Entretien de recueil · Prise des médicaments","q","Avez-vous des difficultés à les prendre (gélules trop grosses, bouche sèche, déglutition difficile) ? Écrasez-vous ou ouvrez-vous certains médicaments ?"],
    ["bpm","Entretien de recueil · Prise des médicaments","q","Aimeriez-vous être aidé(e) dans la prise de vos médicaments ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Ce matin, avez-vous oublié de prendre votre traitement ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Depuis la dernière consultation, avez-vous déjà été en panne de médicaments ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Vous est-il arrivé de prendre votre traitement en retard par rapport à l’heure habituelle ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Vous est-il arrivé de ne pas le prendre parce que, certains jours, votre mémoire vous fait défaut ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Vous est-il arrivé de ne pas le prendre parce que vous aviez l’impression qu’il vous faisait plus de mal que de bien ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","q","Girerd — Pensez-vous que vous avez trop de médicaments à prendre ?"],
    ["bpm","Entretien de recueil · Observance (Girerd)","","Compter 1 point par réponse « non » : 6 = bonne observance, 4 ou 5 = faible observance, 3 ou moins = non-observance."],
    ["bpm","Entretien de recueil · Clôture","q","Avez-vous des questions ou des remarques ?"],
    ["bpm","Entretien de recueil · Clôture","","Rappeler le prochain rendez-vous (entretien-conseil) et le fait que le pharmacien va analyser l’ensemble des traitements."],
    ["bpm","Analyse (hors patient)","","Vérifier pour chaque médicament les posologies et les contre-indications, puis les interactions avec le logiciel métier en incluant l’automédication."],
    ["bpm","Analyse (hors patient)","a","Rechercher les associations à risque chez la personne âgée : au moins 3 psychotropes, 2 benzodiazépines, 2 antidépresseurs, 2 anti-inflammatoires, 4 antihypertenseurs, associations d’anticholinergiques."],
    ["bpm","Analyse (hors patient)","a","Repérer les médicaments à risque élevé chez la personne âgée : anticoagulants, diurétiques, IEC/ARA2, benzodiazépines, hypoglycémiants, anticholinergiques, AINS."],
    ["bpm","Analyse (hors patient)","","Conclure : observance (score de Girerd), mésusage éventuel, automédication, allergies, problèmes de forme galénique, effets indésirables, ruptures de traitement."],
    ["bpm","Analyse (hors patient)","","Pour les patients de 75 ans et plus autonomes, faire le repérage de la fragilité. Faire le point sur les vaccinations (DTP, grippe, zona, pneumocoque)."],
    ["bpm","Analyse (hors patient)","","Rédiger la fiche d’analyse et l’adresser au médecin traitant par messagerie sécurisée, puis l’enregistrer dans le DMP."],
    ["bpm","Entretien-conseil · Explications","e","Expliquer au patient le résultat de l’analyse et les points d’amélioration, avec des mots simples."],
    ["bpm","Entretien-conseil · Explications","","Remettre et commenter le plan de posologie personnalisé : médicament, dosage, horaires matin/midi/soir/coucher, durée, explications et conseils."],
    ["bpm","Entretien-conseil · Explications","e","Oubli ou double prise : ne jamais prendre en double pour rattraper un oubli. En cas de double prise, contacter rapidement le médecin traitant."],
    ["bpm","Entretien-conseil · Explications","e","Donner les conseils hygiéno-diététiques adaptés et rappeler de ne pas prendre de médicament sans avis en automédication."],
    ["bpm","Entretien-conseil · Clôture","q","Avez-vous des questions ou des inquiétudes ?"],
    ["bpm","Entretien-conseil · Clôture","","Fixer la date de l’entretien de suivi d’observance et noter la conclusion."],
    ["bpm","Entretien de suivi · Observance","q","Depuis notre dernier entretien, comment se passent vos prises ? Avez-vous appliqué le plan de posologie ?"],
    ["bpm","Entretien de suivi · Observance","q","Avez-vous eu des effets indésirables ou des difficultés (avaler, couper, horaires) ?"],
    ["bpm","Entretien de suivi · Observance","","Vérifier les acquis, noter les changements de traitement et alerter le médecin traitant si besoin."],

    ["enceinte","1 · Proposer l’entretien","e","Présenter l’objectif : sensibiliser au risque des médicaments pendant la grossesse et à l’importance de la vaccination. L’entretien est unique, à un moment choisi avec la patiente."],
    ["enceinte","1 · Proposer l’entretien","","Recevoir la patiente dans l’espace de confidentialité, sans la culpabiliser."],
    ["enceinte","2 · Médicaments et grossesse","q","Prenez-vous actuellement des médicaments, sur ordonnance ou en automédication ?"],
    ["enceinte","2 · Médicaments et grossesse","","Vérifier qu’aucun traitement en automédication n’est dangereux pour le fœtus."],
    ["enceinte","2 · Médicaments et grossesse","a","Rappeler les risques tératogènes et fœtotoxiques de certains médicaments : ne rien prendre sans avis d’un médecin, d’une sage-femme ou d’un pharmacien."],
    ["enceinte","2 · Médicaments et grossesse","","Aborder les risques à l’aide des supports ANSM (flyers pharmaciens, fiche programme de prévention des grossesses)."],
    ["enceinte","3 · Vaccination","q","Êtes-vous à jour de vos vaccins ? Avez-vous parlé de la vaccination avec votre médecin ou votre sage-femme ?"],
    ["enceinte","3 · Vaccination","e","Rappeler l’importance de la vaccination pendant la grossesse : grippe, Covid, coqueluche et VRS."],
    ["enceinte","4 · Documents","","Remettre le flyer ANSM destiné aux femmes enceintes."],
    ["enceinte","4 · Documents","","Envoyer par e-mail (espace numérique de santé de la patiente) le lien vers la page « femme enceinte » d’ameli.fr et le guide de l’Assurance Maladie sur les étapes de la grossesse."],
    ["enceinte","5 · Clôture","q","Avez-vous des questions ?"],
    ["enceinte","5 · Clôture","","Facturer l’entretien au comptoir avec la carte Vitale (code acte EFE), facturé seul, avec numéro d’identification du pharmacien en prescripteur et en exécutant."],

    ["opioides","1 · Repérer et proposer","","Identifier le patient éligible : 18 ans ou plus, antalgique opioïde de palier II, deuxième délivrance (premier renouvellement) pour une prescription de plus d’un mois. Un seul entretien valorisable par patient sur 12 mois."],
    ["opioides","1 · Repérer et proposer","","Proposer l’entretien sans culpabiliser, au moment de la délivrance, dans un espace confidentiel."],
    ["opioides","1 · Repérer et proposer","","Vérifier avant : identité et âge, médecin prescripteur, indication, médicament, dosage, posologie, durée, date de début, autres médicaments dont l’automédication."],
    ["opioides","2 · Règles de prescription","e","Tramadol, codéine, dihydrocodéine : durée maximale de prescription orale de 12 semaines (au-delà, nouvelle ordonnance). Ordonnance sécurisée. Délivrer les plus petits conditionnements adaptés."],
    ["opioides","2 · Règles de prescription","e","Le tramadol est réservé aux douleurs modérées à intenses, pour la durée la plus courte possible. Non recommandé dans la migraine."],
    ["opioides","3 · Évaluer le mésusage (POMI)","q","POMI — Avez-vous déjà pris ce médicament anti-douleur en quantité plus importante que prescrit ?"],
    ["opioides","3 · Évaluer le mésusage (POMI)","q","POMI — Avez-vous déjà pris ce médicament plus souvent que prescrit, en réduisant le délai entre deux prises ?"],
    ["opioides","3 · Évaluer le mésusage (POMI)","q","POMI — Avez-vous déjà eu besoin de faire renouveler votre ordonnance plus tôt que prévu ?"],
    ["opioides","3 · Évaluer le mésusage (POMI)","q","POMI — Un médecin vous a-t-il déjà dit que vous en preniez trop ?"],
    ["opioides","3 · Évaluer le mésusage (POMI)","q","POMI — Avez-vous déjà eu la sensation de planer ou ressenti un effet stimulant après l’avoir pris ?"],
    ["opioides","3 · Évaluer le mésusage (POMI)","a","Score POMI de 2 réponses « oui » ou plus : risque actuel de mésusage. Alerter le médecin prescripteur et le médecin traitant par messagerie sécurisée."],
    ["opioides","4 · Bon usage et sécurité","q","Combien de comprimés prenez-vous réellement par jour ? Respectez-vous les horaires et l’intervalle entre les prises ?"],
    ["opioides","4 · Bon usage et sécurité","q","Le traitement soulage-t-il suffisamment votre douleur ? Que faites-vous en cas d’oubli ou de manque de médicament ?"],
    ["opioides","4 · Bon usage et sécurité","e","Respecter strictement la prescription (dose, voie, horaires, durée) : ne pas augmenter les doses ni poursuivre sans avis médical. Prendre la dose minimale efficace."],
    ["opioides","4 · Bon usage et sécurité","e","Effets indésirables fréquents et impact sur la vie quotidienne : prudence en conduite (voiture, deux-roues) et avec les machines dangereuses."],
    ["opioides","4 · Bon usage et sécurité","e","Arrêt : diminuer progressivement la posologie pour éviter un syndrome de sevrage, et en surveiller les signes."],
    ["opioides","4 · Bon usage et sécurité","a","Attention au paracétamol associé : dose maximale de 4 g par jour chez l’adulte, en comptant les médicaments sans ordonnance."],
    ["opioides","4 · Bon usage et sécurité","e","Ne pas stocker d’opioïde : rapporter les médicaments non utilisés à la pharmacie. Ne jamais donner son traitement à une autre personne."],
    ["opioides","5 · Signes d’alerte","a","Rechercher : somnolence inhabituelle, vertiges, confusion, nausées et vomissements, constipation, difficultés respiratoires, augmentation progressive des doses, difficulté à diminuer ou arrêter, alcool, benzodiazépines ou sédatifs associés."],
    ["opioides","5 · Signes d’alerte","a","Surdosage (somnolence profonde, respiration lente ou difficile, confusion, lèvres bleutées, perte de connaissance) : appeler le 15 ou le 112, ne pas laisser la personne seule, dire qu’elle a pris un opioïde."],
    ["opioides","6 · Conclure et tracer","e","Si aucun signal inquiétant : valider la compréhension, rappeler les règles de bon usage et conseiller de revenir en cas de douleur mal contrôlée, d’effet indésirable ou de difficulté à réduire."],
    ["opioides","6 · Conclure et tracer","","Si POMI de 2 ou plus : rester factuel et non jugeant, demander l’accord du patient, transmettre les conclusions au prescripteur et au médecin traitant, ne pas modifier le traitement de sa propre initiative."],
    ["opioides","6 · Conclure et tracer","q","Pouvez-vous me redire comment vous allez prendre ce traitement ?"],
    ["opioides","6 · Conclure et tracer","","Tracer dans le dossier et le DMP : réponses POMI et score, conseils, problèmes identifiés, actions et professionnels contactés, opposition éventuelle du patient."],

    ["prevention","1 · Préparer l’entretien","","Vérifier l’âge du patient (18-25, 45-50, 60-65 ou 70-75 ans) et utiliser l’auto-questionnaire de sa tranche d’âge. Prévoir 30 à 45 minutes dans l’espace de confidentialité."],
    ["prevention","1 · Préparer l’entretien","e","Présenter le bilan prévention : faire le point sur sa santé et construire ensemble un plan personnalisé de prévention. Il est pris en charge par l’Assurance Maladie."],
    ["prevention","2 · Situation et antécédents","q","Avez-vous des enfants à la maison ? Aidez-vous un proche ? Pouvez-vous compter sur quelqu’un en cas de besoin ?"],
    ["prevention","2 · Situation et antécédents","q","Vos conditions de vie ou de travail sont-elles difficiles ou pénibles ?"],
    ["prevention","2 · Situation et antécédents","q","Avez-vous ou avez-vous eu une maladie ou un facteur de risque (hypertension, diabète, cholestérol, maladie cardiovasculaire, cancer, maladie respiratoire) ? Y a-t-il des maladies connues dans votre famille proche ?"],
    ["prevention","2 · Situation et antécédents","q","Suivez-vous un traitement ? Quand a eu lieu votre dernière prise de sang ?"],
    ["prevention","3 · Activité physique et alimentation","q","Combien de fois par semaine faites-vous au moins 30 minutes d’activité physique ?"],
    ["prevention","3 · Activité physique et alimentation","q","Combien de temps passez-vous assis(e) par jour, et devant un écran hors travail ?"],
    ["prevention","3 · Activité physique et alimentation","q","Combien de portions de fruits et légumes mangez-vous par jour ? À quelle fréquence mangez-vous des aliments gras, sucrés ou salés ?"],
    ["prevention","3 · Activité physique et alimentation","q","Avez-vous constaté une variation de poids récente, des gonflements des jambes, une toux fréquente, un essoufflement, des pauses respiratoires la nuit ?"],
    ["prevention","4 · Vaccins et dépistages","q","Êtes-vous à jour de vos vaccins et rappels ? Avez-vous votre carnet ?"],
    ["prevention","4 · Vaccins et dépistages","q","Avez-vous réalisé les dépistages recommandés pour votre âge (cancer colorectal, sein, col de l’utérus) ?"],
    ["prevention","4 · Vaccins et dépistages","q","Concernant la santé sexuelle, êtes-vous dans une situation qui justifie un dépistage ou une protection ?"],
    ["prevention","5 · Addictions","q","Consommez-vous du tabac, de l’alcool ou d’autres substances ? À quelle fréquence ?"],
    ["prevention","5 · Addictions","","Repérer les consommations à risque et proposer, si le patient le souhaite, un accompagnement ou une orientation."],
    ["prevention","6 · Plan personnalisé de prévention","","Construire avec le patient 1 à 3 objectifs prioritaires de prévention."],
    ["prevention","6 · Plan personnalisé de prévention","","Pour chaque objectif : noter les obstacles, les actions concrètes à mettre en place, et les ressources ou professionnels à consulter."],
    ["prevention","6 · Plan personnalisé de prévention","","Remettre le plan au patient et l’orienter vers un médecin si un facteur de risque ou un symptôme nécessite un avis."]
  ]$json$::jsonb) with ordinality as s(elem, ord)
join (
  select k.cle, te.id as type_id
  from (values
    ('avk', 'Entretien AVK'),
    ('aod', 'Entretien AOD'),
    ('asthme', 'Entretien asthme'),
    ('onco', 'Entretien anticancéreux oraux'),
    ('bpm', 'Bilan partagé de médication (BPM)'),
    ('enceinte', 'Entretien femme enceinte'),
    ('opioides', 'Entretien opioïdes'),
    ('prevention', 'Bilan de prévention')
  ) as k(cle, nom)
  join public.types_entretien te on te.nom = k.nom
  join public.officines o on o.id = te.officine_id and o.nom = 'Pharmacie Rome Village'
) tc on tc.cle = s.elem->>0;
